const varA = JSON.parse($input.item.json.variant_a);
const varB = JSON.parse($input.item.json.variant_b);

// Z-test for proportions
const pA = varA.conversions / varA.visitors;
const pB = varB.conversions / varB.visitors;
const pPool = (varA.conversions + varB.conversions) / (varA.visitors + varB.visitors);
const se = Math.sqrt(pPool * (1 - pPool) * (1/varA.visitors + 1/varB.visitors));
const z = se > 0 ? Math.abs(pA - pB) / se : 0;

const confidence = z > 2.576 ? 99 : z > 1.96 ? 95 : z > 1.645 ? 90 : z > 1.28 ? 80 : 50;
const significant = confidence >= 95;

const lift = pA > 0 ? (((pB - pA) / pA) * 100).toFixed(1) : 0;
const winner = pB > pA ? 'B' : pA > pB ? 'A' : 'tie';

return [{ json: {
  variant_a: { ...varA, conversion_rate: (pA * 100).toFixed(2) },
  variant_b: { ...varB, conversion_rate: (pB * 100).toFixed(2) },
  lift_percent: parseFloat(lift),
  z_score: z.toFixed(2),
  confidence_level: confidence,
  statistically_significant: significant,
  winner,
  test_name: $input.item.json.test_name,
  hypothesis: $input.item.json.hypothesis,
  duration_days: $input.item.json.test_duration_days
} }];

